import"./main.min.js";import"./slider.min.js";import"./common.min.js";document.addEventListener("DOMContentLoaded",()=>{const s=document.querySelectorAll(".carousel3d__item"),c=document.querySelectorAll(".dot");let a=1;function l(t){a=t,s.forEach((e,d)=>{e.classList.remove("left","active","right"),d===a?e.classList.add("active"):d===(a-1+s.length)%s.length?e.classList.add("left"):d===(a+1)%s.length&&e.classList.add("right")}),c.forEach(e=>e.classList.remove("active")),c[a].classList.add("active")}c.forEach(t=>{t.addEventListener("click",()=>{l(parseInt(t.dataset.index))})}),s.forEach((t,e)=>{t.addEventListener("click",()=>{l(e)})})});
